# Older turns are dropped first; the system message at index 0 is always kept.
_MAX_SESSION_BYTES = 50 * 1024
_JSON_LIST_OVERHEAD_BYTES = 2
_JSON_LIST_SEPARATOR_BYTES = 2

_THINK_OPEN = "<think>"
_THINK_CLOSE = "</think>"


def _partial_tag_suffix(text: str, tag: str) -> str:
    """Return the longest suffix of ``text`` that is a proper prefix of ``tag``.

    Used to detect a partially-streamed ``<think>``/``</think>`` tag at the end of
    a buffer so it can be held back until the next chunk arrives. A full occurrence
    of ``tag`` is handled by the caller before this is consulted, so only prefixes
    shorter than the full tag are considered.
    """
    for k in range(min(len(text), len(tag) - 1), 0, -1):
        if text[-k:] == tag[:k]:
            return text[-k:]
    return ""


def _strip_think_blocks(buf: str, in_think: bool) -> tuple[str, str, bool]:
    """Strip ``<think>...</think>`` spans from a streaming text buffer.

    Returns ``(emit, remaining, new_in_think)`` where ``emit`` is the text safe to
    show users, ``remaining`` holds any partial open/close tag that must be re-fed
    with the next chunk, and ``new_in_think`` indicates whether the parser is inside
    a think block after processing ``buf``.
    """
    emit: list[str] = []
    i = 0
    while i < len(buf):
        if in_think:
            idx = buf.find(_THINK_CLOSE, i)
            if idx == -1:
                # No closing tag yet; discard everything but hold a partial tag.
                return "".join(emit), _partial_tag_suffix(buf[i:], _THINK_CLOSE), True
            i = idx + len(_THINK_CLOSE)
            in_think = False
        else:
            idx = buf.find(_THINK_OPEN, i)
            if idx == -1:
                tail = buf[i:]
                partial = _partial_tag_suffix(tail, _THINK_OPEN)
                emit.append(tail[: len(tail) - len(partial)])
                return "".join(emit), partial, False
            emit.append(buf[i:idx])
            i = idx + len(_THINK_OPEN)
            in_think = True
    return "".join(emit), "", in_think


def _merge_tool_call_chunk(acc: list[dict[str, Any]], chunk: dict[str, Any]) -> None:
    """Merge a streaming tool-call delta ``chunk`` into ``acc`` in place.

    Tool calls are identified by ``chunk["index"]``. The first chunk for an index
    supplies the ``id`` and ``function.name``; every chunk appends its
    ``function.arguments`` fragment so the full argument string is accumulated.
    """
    index = chunk.get("index", 0)
    entry = next((e for e in acc if e["index"] == index), None)
    if entry is None:
        entry = {"index": index, "id": None, "function": {"name": None, "arguments": ""}}
        acc.append(entry)

    if chunk.get("id"):
        entry["id"] = chunk["id"]
    fn = chunk.get("function") or {}
    if fn.get("name"):
        entry["function"]["name"] = fn["name"]
    if fn.get("arguments"):
        entry["function"]["arguments"] += fn["arguments"]


def _message_size_bytes(message: dict[str, Any]) -> int:
    return len(json.dumps(message).encode())


def _trim_session(messages: list[dict[str, Any]]) -> list[dict[str, Any]]:
    message_sizes = [_message_size_bytes(message) for message in messages]
    total_size = _JSON_LIST_OVERHEAD_BYTES + sum(message_sizes)
    if len(message_sizes) > 1:
        total_size += (len(message_sizes) - 1) * _JSON_LIST_SEPARATOR_BYTES

    while total_size > _MAX_SESSION_BYTES and len(messages) > 2:
        messages.pop(1)
        total_size -= message_sizes.pop(1) + _JSON_LIST_SEPARATOR_BYTES
    return messages


